function validate([rectangles]) {
  if (!Array.isArray(rectangles) || rectangles.length < 1 || rectangles.length > 200) return 'rectangles needs 1 to 200 entries.';
  for (const r of rectangles) {
    if (!Array.isArray(r) || r.length !== 4) return 'Each rectangle is [x1, y1, x2, y2].';
    if (r.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Coordinates are integers from 0 to 10^9.';
    if (r[0] >= r[2] || r[1] >= r[3]) return 'Each rectangle needs x1 < x2 and y1 < y2.';
  }
  return null;
}

