function rectangleArea(rectangles) {
  const MOD = 1000000007n;
  const ys = [...new Set(rectangles.flatMap(([, y1, , y2]) => [y1, y2]))].sort((a, b) => a - b);
  const index = new Map(ys.map((y, i) => [y, i]));
  const events = [];
  for (const [x1, y1, x2, y2] of rectangles) {
    events.push([x1, 1, index.get(y1), index.get(y2)]);
    events.push([x2, -1, index.get(y1), index.get(y2)]);
  }
  events.sort((a, b) => a[0] - b[0]);

  const size = ys.length - 1;
  const count = new Array(4 * size).fill(0);
  const covered = new Array(4 * size).fill(0);
  const update = (node, lo, hi, from, to, delta) => {
    if (to <= lo || hi <= from) return;
    if (from <= lo && hi <= to) {
      count[node] += delta;
    } else {
      const mid = (lo + hi) >> 1;
      update(2 * node, lo, mid, from, to, delta);
      update(2 * node + 1, mid, hi, from, to, delta);
    }
    if (count[node] > 0) {
      covered[node] = ys[hi] - ys[lo];
    } else if (hi - lo === 1) {
      covered[node] = 0;
    } else {
      covered[node] = covered[2 * node] + covered[2 * node + 1];
    }
  };

  let total = 0n;
  let prevX = events[0][0];
  for (const [x, delta, from, to] of events) {
    total += BigInt(covered[1]) * BigInt(x - prevX);
    update(1, 0, size, from, to, delta);
    prevX = x;
  }
  return Number(total % MOD);
}

