function rectangleArea(rectangles) {
  const xs = [...new Set(rectangles.flatMap(r => [r[0], r[2]]))].sort((a, b) => a - b);
  const ys = [...new Set(rectangles.flatMap(r => [r[1], r[3]]))].sort((a, b) => a - b);
  let area = 0n;
  for (let i = 0; i + 1 < xs.length; i++) {
    for (let j = 0; j + 1 < ys.length; j++) {
      const inside = rectangles.some(r => r[0] <= xs[i] && xs[i + 1] <= r[2] && r[1] <= ys[j] && ys[j + 1] <= r[3]);
      if (inside) area += BigInt(xs[i + 1] - xs[i]) * BigInt(ys[j + 1] - ys[j]);
    }
  }
  return Number(area % 1000000007n);
}

