function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const span = rand() < 0.5 ? 1000000000 : 1000;
    return [Array.from({ length: 200 }, () => {
      const x1 = int(0, span - 1), y1 = int(0, span - 1);
      return [x1, y1, int(x1 + 1, Math.min(span, x1 + Math.ceil(span / 3))), int(y1 + 1, Math.min(span, y1 + Math.ceil(span / 3)))];
    })];
  }
  const n = int(1, 6);
  const huge = rand() < 0.2;
  const span = huge ? 1000000000 : int(2, 10);
  const rectangles = [];
  for (let i = 0; i < n; i++) {
    if (i > 0 && rand() < 0.15) { rectangles.push(rectangles[int(0, i - 1)].slice()); continue; }
    const x1 = int(0, span - 1), y1 = int(0, span - 1);
    rectangles.push([x1, y1, int(x1 + 1, span), int(y1 + 1, span)]);
  }
  return [rectangles];
}
